    unsigned si_rot;
    uint8_t  sacch_buf[23];
    bool     sacch_have;
    bool     sacch_real;

    int      serving_arfcn;
    uint8_t  sb_bsic;
    uint32_t sb_fn;
    bool     sb_valid;
    uint32_t sb_capture_fn;

    uint8_t  agch_buf[23];
    bool     agch_valid;
